import React, { useState, useRef } from 'react';
import { 
  Trash2, Map, Calendar, Star, LineChart, Users, 
  HardHat, FileText, Activity, ShieldAlert, 
  User, Bell, LogOut, X, Fingerprint, ChevronRight
} from 'lucide-react';

// Import your separate tab components (We will create these next)
import BinMonitoringTab from '../tabs/BinMonitoringTab';
import ZonesTab from '../tabs/ZonesTab';
import ScheduleTab from '../tabs/ScheduleTab';
import PointsTab from '../tabs/PointsTab';
import AnalyticsTab from '../tabs/AnalyticsTab';
import CitizensTab from '../tabs/CitizensTab';
import WorkersTab from '../tabs/WorkersTab';
import ReportsTab from '../tabs/ReportsTab';

const Dashboard = ({ onLogout }) => {
  const [activeTab, setActiveTab] = useState("BINS");
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const scrollRef = useRef(null);

  const tabs = [
    { id: "BINS", label: "Bins", icon: <Trash2 size={22} />, component: <BinMonitoringTab /> },
    { id: "ZONES", label: "Zones", icon: <Map size={22} />, component: <ZonesTab /> },
    { id: "SCHEDULE", label: "Plan", icon: <Calendar size={22} />, component: <ScheduleTab /> },
    { id: "POINTS", label: "Vault", icon: <Star size={22} />, component: <PointsTab /> },
    { id: "ANALYTICS", label: "Data", icon: <LineChart size={22} />, component: <AnalyticsTab /> },
    { id: "CITIZENS", label: "Social", icon: <Users size={22} />, component: <CitizensTab /> },
    { id: "WORKERS", label: "Nodes", icon: <HardHat size={22} />, component: <WorkersTab /> },
    { id: "REPORTS", label: "Alerts", icon: <FileText size={22} />, component: <ReportsTab /> },
  ];

  const scrollToTab = (tabId, index) => {
    setActiveTab(tabId);
    scrollRef.current.scrollTo({
      left: index * window.innerWidth,
      behavior: "smooth"
    });
  };

  const handleScroll = () => {
    const index = Math.round(scrollRef.current.scrollLeft / window.innerWidth);
    if (tabs[index] && tabs[index].id !== activeTab) {
      setActiveTab(tabs[index].id);
    }
  };

  return (
    <div className="h-screen w-full bg-[#FDFAD8] overflow-hidden relative font-sans">

      {/* --- TOP FIXED HUD --- */}
      <header className="fixed top-0 w-full z-[60] p-6 flex justify-between items-center pointer-events-none">
        <div className="bg-[#AB1717] border-4 border-[#47510B] p-4 rounded-[25px] red-stack-shadow pointer-events-auto flex items-center gap-4">
          <ShieldAlert className="text-[#CAD23C]" size={28} />
          <h2 className="text-2xl font-black italic text-[#FDFAD8] uppercase tracking-tighter">
            {activeTab}<span className="text-[#CAD23C]">.</span>
          </h2>
        </div>

        <div className="flex gap-3 pointer-events-auto">
          <button onClick={() => setIsProfileOpen(true)} className="bg-[#47510B] border-4 border-[#CAD23C]/30 p-3 rounded-2xl text-[#FDFAD8] hover:scale-105 transition-all shadow-xl">
            <User size={24} />
          </button>
          <button onClick={onLogout} className="bg-[#FDFAD8] border-4 border-[#AB1717] p-3 rounded-2xl text-[#AB1717] hover:bg-[#AB1717] hover:text-white transition-all shadow-xl">
            <LogOut size={24} />
          </button>
        </div>
      </header>

      {/* --- MAIN SCROLLABLE CAROUSEL --- */}
      <main 
        ref={scrollRef} 
        onScroll={handleScroll}
        className="h-full w-full flex overflow-x-auto snap-x snap-mandatory no-scrollbar"
      >
        {tabs.map((tab) => (
          <section key={tab.id} className="min-w-full h-full snap-start pt-32 pb-32 px-6 md:px-12">
            {/* The Tab Content is injected here */}
            <div className="w-full h-full max-w-[1400px] mx-auto">
                {tab.component}
            </div>
          </section>
        ))}
      </main>

      {/* --- BOTTOM FIXED NAVIGATION TRAY --- */}
      <footer className="fixed bottom-8 left-1/2 -translate-x-1/2 z-[60] w-fit">
        <nav className="bg-[#47510B] border-[6px] border-[#AB1717] p-3 rounded-[40px] shadow-[0_15px_40px_rgba(0,0,0,0.3)] flex items-center gap-2">
          {tabs.map((tab, index) => (
            <button 
              key={tab.id} 
              onClick={() => scrollToTab(tab.id, index)}
              className={`flex items-center gap-3 px-5 py-3 rounded-[30px] transition-all duration-300 group
                ${activeTab === tab.id ? "bg-[#CAD23C] scale-110 shadow-lg" : "text-[#FDFAD8]/40 hover:text-[#FDFAD8]"}`}
            >
              <div className={activeTab === tab.id ? "text-[#47510B]" : ""}>{tab.icon}</div>
              {activeTab === tab.id && (
                <span className="text-[11px] font-[1000] uppercase tracking-widest text-[#47510B]">{tab.label}</span>
              )}
            </button>
          ))}
        </nav>
      </footer>

      {/* --- PROFILE OVERLAY (Same logic as your example) --- */}
      {isProfileOpen && (
        <ProfileLayer user={{name: "Admin_01"}} onClose={() => setIsProfileOpen(false)} />
      )}
    </div>
  );
};
